{
  "packet_id": "H6-T01-3",
  "claims": [
    {
      "claim_id": "C001",
      "fields": ["state"],
      "component": {
        "component_id": "C001.component",
        "value": "The reported incidence is 19 late starts among 74 bookings over six weeks.",
        "scope": "Reported figures, not independently verified findings; the meaning of late start remains to be established.",
        "provenance": {
          "refs": [{"source_id": "P001", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the reported count, denominator and observation period."
        }
      }
    },
    {
      "claim_id": "C002",
      "fields": ["state"],
      "component": {
        "component_id": "C002.component",
        "value": "Calendar availability did not consistently translate into timely starts, and competing explanations should be investigated.",
        "scope": "The reported depot problem; no particular explanation is established by this discrepancy.",
        "provenance": {
          "refs": [{"source_id": "P001", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span identifies the discrepancy and frames its explanation as contested."
        }
      }
    },
    {
      "claim_id": "C003",
      "fields": ["state"],
      "component": {
        "component_id": "C003.component",
        "value": "Delayed equipment returns are a hypothesis for the late starts, not an established cause.",
        "scope": "One competing explanation for the calendar-to-start discrepancy.",
        "provenance": {
          "refs": [
            {"source_id": "P002", "role": "SUPPORT"},
            {"source_id": "P001", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P002 supplies the hypothesis and its epistemic limit; P001 identifies the problem being explained."
        }
      }
    },
    {
      "claim_id": "C004",
      "fields": ["state"],
      "component": {
        "component_id": "C004.component",
        "value": "Unfinished cleaning is a hypothesis for the late starts, not an established cause.",
        "scope": "One competing explanation for the calendar-to-start discrepancy.",
        "provenance": {
          "refs": [
            {"source_id": "P002", "role": "SUPPORT"},
            {"source_id": "P001", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P002 supplies the hypothesis and its epistemic limit; P001 identifies the problem being explained."
        }
      }
    },
    {
      "claim_id": "C005",
      "fields": ["state"],
      "component": {
        "component_id": "C005.component",
        "value": "Inaccurate availability updates are a hypothesis for the late starts, not an established cause.",
        "scope": "One competing explanation for the calendar-to-start discrepancy.",
        "provenance": {
          "refs": [
            {"source_id": "P002", "role": "SUPPORT"},
            {"source_id": "P001", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P002 supplies the hypothesis and its epistemic limit; P001 identifies the problem being explained."
        }
      }
    },
    {
      "claim_id": "C006",
      "fields": ["state"],
      "component": {
        "component_id": "C006.component",
        "value": "Delayed collection is a hypothesis for the late starts, not an established cause.",
        "scope": "One competing explanation for the calendar-to-start discrepancy.",
        "provenance": {
          "refs": [
            {"source_id": "P002", "role": "SUPPORT"},
            {"source_id": "P001", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P002 supplies the hypothesis and its epistemic limit; P001 identifies the problem being explained."
        }
      }
    },
    {
      "claim_id": "C007",
      "fields": ["state"],
      "component": {
        "component_id": "C007.component",
        "value": "Linking records to equipment and bookings is an assumption that must be checked first.",
        "scope": "A prerequisite assumed by the proposed investigation, not a demonstrated capability of the records.",
        "provenance": {
          "refs": [{"source_id": "P003", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly couples the linkage assumption with prior verification."
        }
      }
    },
    {
      "claim_id": "C008",
      "fields": ["state", "limit"],
      "component": {
        "component_id": "C008.component",
        "value": "Scheduled start, physical return, cleaning completion, readiness for collection, collection and actual work start must be distinguished as different events or milestones.",
        "scope": "Event definitions in the booking timelines; this distinction does not assert that their recorded times must always differ.",
        "provenance": {
          "refs": [
            {"source_id": "P004", "role": "SUPPORT"},
            {"source_id": "P031", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P004 supplies the full distinction; P031 repeats the distinction among readiness, collection and work start."
        }
      }
    },
    {
      "claim_id": "C009",
      "fields": ["state"],
      "component": {
        "component_id": "C009.component",
        "value": "The investigation must establish which event or measure the reported late-start classification refers to.",
        "scope": "The mapping leaves the actual referent of late start unresolved.",
        "provenance": {
          "refs": [{"source_id": "P005", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The instruction to establish what late start measures directly supports this unresolved measurement requirement."
        }
      }
    },
    {
      "claim_id": "C010",
      "fields": ["state"],
      "component": {
        "component_id": "C010.component",
        "value": "Comparisons should use the existing lateness rule if one exists; otherwise a rule should be agreed before comparison.",
        "scope": "Conditional measurement procedure; the mapping neither supplies a threshold nor establishes whether a rule already exists.",
        "provenance": {
          "refs": [{"source_id": "P005", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span states both branches of the rule-selection procedure and the timing requirement."
        }
      }
    },
    {
      "claim_id": "C011",
      "fields": ["operation", "signal"],
      "component": {
        "component_id": "C011.component",
        "value": "The investigation should examine all reported late cases and use the other bookings to check whether suspected or supported problem patterns also occur without lateness.",
        "scope": "Comparison across the reported booking set; occurrence among timely bookings is to be checked, not assumed.",
        "provenance": {
          "refs": [
            {"source_id": "P007", "role": "SUPPORT"},
            {"source_id": "P020", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "Both spans prescribe comparison with bookings without lateness; P007 supplies the complete late-case review."
        }
      }
    },
    {
      "claim_id": "C012",
      "fields": ["operation", "signal"],
      "component": {
        "component_id": "C012.component",
        "value": "Missing entries, unsupported intervals and missing coverage should remain explicit alongside supported sequences.",
        "scope": "Representation of evidential gaps in the investigation; no events are inferred merely to fill those gaps.",
        "provenance": {
          "refs": [
            {"source_id": "P008", "role": "SUPPORT"},
            {"source_id": "P019", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "The spans jointly require preservation and reporting of the specified gaps."
        }
      }
    },
    {
      "claim_id": "C013",
      "fields": ["operation"],
      "component": {
        "component_id": "C013.component",
        "value": "Uncertainty in matching records should be preserved explicitly.",
        "scope": "Uncertain matches encountered while assembling booking-level timelines.",
        "provenance": {
          "refs": [
            {"source_id": "P008", "role": "SUPPORT"},
            {"source_id": "P006", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P008 states the uncertainty-preservation requirement; P006 identifies the record-assembly context."
        }
      }
    },
    {
      "claim_id": "C014",
      "fields": ["operation"],
      "component": {
        "component_id": "C014.component",
        "value": "Each material claim should carry information about the observer, observation, recording time, direct access and possible copying from another record.",
        "scope": "The proposed source-assessment procedure; collecting these attributes does not itself establish credibility or independence.",
        "provenance": {
          "refs": [{"source_id": "P009", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span specifies these attributes for every material claim."
        }
      }
    },
    {
      "claim_id": "C015",
      "fields": ["operation"],
      "component": {
        "component_id": "C015.component",
        "value": "Independent checks should be sought through existing crew and depot accounts or contemporaneous records where available.",
        "scope": "A proposed verification route conditional on availability; those accounts and records are not declared independent merely by being available.",
        "provenance": {
          "refs": [{"source_id": "P010", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span specifies independently grounded checks, their possible sources and the availability qualifier."
        }
      }
    },
    {
      "claim_id": "C016",
      "fields": ["operation"],
      "component": {
        "component_id": "C016.component",
        "value": "Questions about specific events should precede presentation of a proposed explanation.",
        "scope": "Elicitation of checks and accounts; no additional claim about the size or certainty of any resulting bias reduction is supplied.",
        "provenance": {
          "refs": [{"source_id": "P010", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly prescribes this elicitation order."
        }
      }
    },
    {
      "claim_id": "C017",
      "fields": ["operation"],
      "component": {
        "component_id": "C017.component",
        "value": "Disputed handoffs should receive prospective checks within existing staffing, using separate firsthand observations where feasible.",
        "scope": "Planned for days 5–8; separate firsthand observation is conditional on feasibility.",
        "provenance": {
          "refs": [{"source_id": "P011", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the proposed check, its staffing bound, feasibility qualifier and timing."
        }
      }
    },
    {
      "claim_id": "C018",
      "fields": ["operation"],
      "component": {
        "component_id": "C018.component",
        "value": "Conflicting timestamps, definitions and equipment identities should be reconciled without forcing agreement.",
        "scope": "Resolution of discrepancies in the investigation; unresolved disagreement is permitted to remain.",
        "provenance": {
          "refs": [{"source_id": "P012", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span states the reconciliation task and its explicit constraint."
        }
      }
    },
    {
      "claim_id": "C019",
      "fields": ["operation"],
      "component": {
        "component_id": "C019.component",
        "value": "Candidate changes should be compared using corroborated failure patterns, their frequency and delay burden, operational feasibility and possible effects on other crews.",
        "scope": "The comparison scheduled for days 9–10; the mapping gives no numerical weighting among these criteria.",
        "provenance": {
          "refs": [{"source_id": "P013", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly specifies the comparison criteria and schedule."
        }
      }
    },
    {
      "claim_id": "C020",
      "fields": ["operation"],
      "component": {
        "component_id": "C020.component",
        "value": "If return-to-ready delays are verified, a turnaround allowance is a candidate change.",
        "scope": "A conditional candidate, not an established remedy or guaranteed delay reduction; the verification threshold is unspecified.",
        "provenance": {
          "refs": [{"source_id": "P014", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly pairs this candidate with verified return-to-ready delays."
        }
      }
    },
    {
      "claim_id": "C021",
      "fields": ["operation"],
      "component": {
        "component_id": "C021.component",
        "value": "If status errors are verified, readiness confirmation before calendar release is a candidate change.",
        "scope": "A conditional candidate, not an established remedy or guaranteed delay reduction; the verification threshold is unspecified.",
        "provenance": {
          "refs": [{"source_id": "P014", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly pairs this candidate and its release timing with verified status errors."
        }
      }
    },
    {
      "claim_id": "C022",
      "fields": ["operation"],
      "component": {
        "component_id": "C022.component",
        "value": "If collection failures are verified, a collection handoff rule is a candidate change.",
        "scope": "A conditional candidate, not an established remedy or guaranteed delay reduction; the verification threshold is unspecified.",
        "provenance": {
          "refs": [{"source_id": "P014", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly pairs this candidate with verified collection failures."
        }
      }
    },
    {
      "claim_id": "C023",
      "fields": ["operation"],
      "component": {
        "component_id": "C023.component",
        "value": "One narrowly scoped, reversible trial should be selected by the two-week deadline.",
        "scope": "A bound on trial selection; the sentence does not require completion of the trial within two weeks.",
        "provenance": {
          "refs": [{"source_id": "P015", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the selection deadline and the trial's scope and reversibility requirements."
        }
      }
    },
    {
      "claim_id": "C024",
      "fields": ["operation"],
      "component": {
        "component_id": "C024.component",
        "value": "Changes should not be combined when their effects could not be distinguished.",
        "scope": "A conditional restriction on trial composition, not a blanket assertion that all combined changes are uninterpretable.",
        "provenance": {
          "refs": [{"source_id": "P015", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span states both the prohibited combination and the condition motivating the restriction."
        }
      }
    },
    {
      "claim_id": "C025",
      "fields": ["signal"],
      "component": {
        "component_id": "C025.component",
        "value": "Agreement or disagreement used in corroboration should be independent and concern the same equipment, booking and handoff.",
        "scope": "The identity and independence conditions for the proposed signal; agreement about different referents is not the specified signal.",
        "provenance": {
          "refs": [{"source_id": "P016", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly gives the independence and shared-reference requirements."
        }
      }
    },
    {
      "claim_id": "C026",
      "fields": ["signal"],
      "component": {
        "component_id": "C026.component",
        "value": "A return entry together with a separately recorded firsthand observation could support a finding that equipment arrived after the next scheduled start.",
        "scope": "An illustrative possibility, not an observed finding; separate recording is not silently strengthened into proven source independence.",
        "provenance": {
          "refs": [{"source_id": "P017", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the example evidence bundle, modal qualification and specific timing conclusion."
        }
      }
    },
    {
      "claim_id": "C027",
      "fields": ["signal"],
      "component": {
        "component_id": "C027.component",
        "value": "A cleaning entry together with an independent readiness check could support a finding that cleaning was still incomplete at the next scheduled start.",
        "scope": "An illustrative possibility, not an observed finding; the temporal reference is the next scheduled start introduced within the same span.",
        "provenance": {
          "refs": [{"source_id": "P017", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the evidence bundle, the possible status finding and the antecedent of its temporal reference."
        }
      }
    },
    {
      "claim_id": "C028",
      "fields": ["signal"],
      "component": {
        "component_id": "C028.component",
        "value": "Calendar availability by itself is insufficient to establish physical readiness.",
        "scope": "An evidential limit on the calendar, not a claim that calendar entries are always inaccurate.",
        "provenance": {
          "refs": [{"source_id": "P018", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly states this insufficiency."
        }
      }
    },
    {
      "claim_id": "C029",
      "fields": ["signal"],
      "component": {
        "component_id": "C029.component",
        "value": "Contradictions should be recorded alongside supported sequences.",
        "scope": "Reporting of the investigation's evidence, including evidence that does not agree with supported sequences.",
        "provenance": {
          "refs": [{"source_id": "P019", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly requires retaining contradictions in the evidence record."
        }
      }
    },
    {
      "claim_id": "C030",
      "fields": ["signal"],
      "component": {
        "component_id": "C030.component",
        "value": "Supported patterns should be counted across bookings.",
        "scope": "Frequency assessment of patterns with support; the mapping does not equate raw record counts with independently supported occurrences.",
        "provenance": {
          "refs": [{"source_id": "P020", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span specifies both the counting unit and the restriction to supported patterns."
        }
      }
    },
    {
      "claim_id": "C031",
      "fields": ["signal"],
      "component": {
        "component_id": "C031.component",
        "value": "Prospective trial observation should include late-start frequency and delay duration, readiness and collection timing, completed or displaced bookings, added workload and unmet cleaning requirements.",
        "scope": "The selected trial's observation set; these are proposed measurements, not outcomes already observed.",
        "provenance": {
          "refs": [{"source_id": "P021", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly specifies the trial's timing, service, workload and cleaning observations."
        }
      }
    },
    {
      "claim_id": "C032",
      "fields": ["inference"],
      "component": {
        "component_id": "C032.component",
        "value": "Convergence among credible sources with independent access increases support for the particular timing or status feature they corroborate.",
        "scope": "Conditional on credibility and independent access, and restricted to the corroborated feature; it does not establish an entire causal explanation.",
        "provenance": {
          "refs": [{"source_id": "P022", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the evidential conditions, direction of support and feature-specific limit."
        }
      }
    },
    {
      "claim_id": "C033",
      "fields": ["inference"],
      "component": {
        "component_id": "C033.component",
        "value": "Repeated supported sequences can justify prioritizing a corresponding change for trial, especially when their timing plausibly explains the delay and comparison bookings strengthen that explanation.",
        "scope": "A qualified justification for trial priority, not proof of cause or benefit; the mapping does not define a minimum repetition count.",
        "provenance": {
          "refs": [{"source_id": "P023", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly states the qualified priority inference and its strengthening conditions."
        }
      }
    },
    {
      "claim_id": "C034",
      "fields": ["inference"],
      "component": {
        "component_id": "C034.component",
        "value": "Selection should favor the feasible change addressing the largest credible, avoidable delay burden without purchasing equipment or adding staff.",
        "scope": "A comparative selection rule constrained by feasibility, credibility, avoidability and existing resources; no burden-calculation formula is supplied.",
        "provenance": {
          "refs": [{"source_id": "P024", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the preferred objective and all stated selection constraints."
        }
      }
    },
    {
      "claim_id": "C035",
      "fields": ["inference"],
      "component": {
        "component_id": "C035.component",
        "value": "Contradictions lower confidence.",
        "scope": "Confidence in the disputed handoff claim or feature; the mapping gives no quantitative confidence adjustment.",
        "provenance": {
          "refs": [{"source_id": "P025", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly states the confidence consequence and identifies the disputed handoff."
        }
      }
    },
    {
      "claim_id": "C036",
      "fields": ["inference"],
      "component": {
        "component_id": "C036.component",
        "value": "Contradictions should direct follow-up toward the disputed handoff.",
        "scope": "A conditional investigation priority when contradictions arise.",
        "provenance": {
          "refs": [{"source_id": "P025", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the operational consequence of encountering contradictions."
        }
      }
    },
    {
      "claim_id": "C037",
      "fields": ["inference"],
      "component": {
        "component_id": "C037.component",
        "value": "If no explanation has adequate independent support by the deadline, a limited readiness-confirmation trial should be selected primarily to resolve uncertainty.",
        "scope": "Fallback selection at the two-week deadline; adequate support and the precise uncertainty-reduction mechanism are not operationally defined.",
        "provenance": {
          "refs": [
            {"source_id": "P026", "role": "SUPPORT"},
            {"source_id": "P015", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P026 supplies the condition, fallback and primary purpose; P015 resolves which deadline is meant."
        }
      }
    },
    {
      "claim_id": "C038",
      "fields": ["inference"],
      "component": {
        "component_id": "C038.component",
        "value": "When readiness confirmation is selected because no explanation has adequate independent support by the deadline, its delay-reduction benefit remains unestablished and should be identified as such.",
        "scope": "The uncertainty-resolution fallback at the two-week deadline; this is not a finding that readiness confirmation has no benefit.",
        "provenance": {
          "refs": [
            {"source_id": "P026", "role": "SUPPORT"},
            {"source_id": "P015", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P026 explicitly preserves the unestablished-benefit qualification under the fallback condition; P015 identifies the deadline."
        }
      }
    },
    {
      "claim_id": "C039",
      "fields": ["inference"],
      "component": {
        "component_id": "C039.component",
        "value": "Trial outcomes should be compared with comparable baseline bookings while accounting for equipment, crew and demand differences.",
        "scope": "The proposed evaluation method; the mapping does not specify matching criteria or an adjustment procedure.",
        "provenance": {
          "refs": [{"source_id": "P027", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly supplies the baseline comparison and the differences to account for."
        }
      }
    },
    {
      "claim_id": "C040",
      "fields": ["inference"],
      "component": {
        "component_id": "C040.component",
        "value": "Improvement in the trial comparison supports continued testing.",
        "scope": "Improvement assessed against comparable baseline bookings with equipment, crew and demand differences accounted for; the conclusion is continued testing.",
        "provenance": {
          "refs": [{"source_id": "P027", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies both the comparison setting and the limited positive inference from improvement."
        }
      }
    },
    {
      "claim_id": "C041",
      "fields": ["inference"],
      "component": {
        "component_id": "C041.component",
        "value": "Improvement in trial outcomes alone does not establish causation.",
        "scope": "The proposed comparison with comparable baseline bookings, including accounting for equipment, crew and demand differences.",
        "provenance": {
          "refs": [{"source_id": "P027", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span expressly limits the causal inference available from improvement."
        }
      }
    },
    {
      "claim_id": "C042",
      "fields": ["limit"],
      "component": {
        "component_id": "C042.component",
        "value": "Separate logs may share an author, so their separation does not guarantee independent evidence.",
        "scope": "A possible source-dependence mechanism, not a finding that the depot logs actually share an author.",
        "provenance": {
          "refs": [{"source_id": "P028", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span names shared authorship as a reason separate logs need not be independent."
        }
      }
    },
    {
      "claim_id": "C043",
      "fields": ["limit"],
      "component": {
        "component_id": "C043.component",
        "value": "Separate logs may contain copied timestamps, so their separation does not guarantee independent evidence.",
        "scope": "A possible copying mechanism, not a finding that copying occurred in these logs.",
        "provenance": {
          "refs": [{"source_id": "P028", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span identifies copied timestamps as a possible source of dependence."
        }
      }
    },
    {
      "claim_id": "C044",
      "fields": ["limit"],
      "component": {
        "component_id": "C044.component",
        "value": "Separate logs may share clock errors, so their separation does not guarantee independent evidence.",
        "scope": "A possible common-error mechanism, not a finding that clock errors occurred in these logs.",
        "provenance": {
          "refs": [{"source_id": "P028", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span identifies shared clock errors as a limitation on treating separate logs as independent."
        }
      }
    },
    {
      "claim_id": "C045",
      "fields": ["limit"],
